fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = arr.len() as isize - 1; // Use isize for easier calculations with indices

    while left <= right {
        let mid = left + (right - left) / 2; // Calculate mid index

        if arr[mid as usize] < target {
            left = mid + 1; // Move right
        } else if arr[mid as usize] > target {
            right = mid - 1; // Move left
        } else {
            // Target found, now check for the first occurrence
            // Move left to find the first occurrence
            if mid == 0 || arr[(mid - 1) as usize] < target {
                return Some(mid as usize); // Found the first occurrence
            }
            right = mid - 1; // Continue searching to the left
        }
    }

    None // Target not found
}